 static void ImportUICallbacks(GameObject go,EMNode n,Dictionary<string,GameObject> nodes,EMPackage package){
  if(!n.hasUI||n.ui.onClick.Count==0)return;var button=go.GetComponent<Button>();foreach(var call in n.ui.onClick){var owner=package.nodes.Single(x=>x.id==call.target);var index=owner.behaviours.FindIndex(b=>b.id==call.behaviour&&b.className==call.className);if(index<0)throw new Exception("UI callback component reference missing");var target=nodes[call.target].GetComponents<MonoBehaviour>().Where(IsUserBehaviour).ToArray()[index];var action=(UnityAction)Delegate.CreateDelegate(typeof(UnityAction),target,call.method);UnityEventTools.AddVoidPersistentListener(button.onClick,action);button.onClick.SetPersistentListenerState(button.onClick.GetPersistentEventCount()-1,(UnityEventCallState)Enum.Parse(typeof(UnityEventCallState),call.callState));}
 }
 static void ImportUI(GameObject go,EMNode n,Dictionary<string,Texture2D> textures,string root){
  if(!n.hasUI)return;var d=n.ui;d.texture=d.texture??"";d.sprite=d.sprite??"";d.spriteName=d.spriteName??"";if(d.pixelsPerUnit<=0)d.pixelsPerUnit=100;if(d.uv==Vector4.zero&&d.texture=="")d.uv=new Vector4(0,0,1,1);var r=(RectTransform)go.transform;r.anchorMin=d.anchorMin;r.anchorMax=d.anchorMax;r.pivot=d.pivot;r.anchoredPosition=d.position;r.sizeDelta=d.size;r.localRotation=Quaternion.identity;r.localScale=Vector3.one;
  if(d.canvas){var canvas=go.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.enabled=d.enabled;canvas.scaleFactor=d.scaleFactor;var scaler=go.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ConstantPixelSize;scaler.scaleFactor=d.scaleFactor;go.AddComponent<GraphicRaycaster>();}
