 static void VerifyUI(GameObject go,EMNode n,Dictionary<Transform,string> ids){
  if(!n.hasUI)return;var read=new EMNode();var p=new EMPackage();ExportUI(go,read,p,ids);var a=n.ui;var b=read.ui;
  if(b==null||p.blockers.Count>0||a.canvas!=b.canvas||a.enabled!=b.enabled||a.visual!=b.visual||a.interactable!=b.interactable||a.buttonEnabled!=b.buttonEnabled||a.raycast!=b.raycast||(a.text??"")!=(b.text??"")||(a.font??"")!=(b.font??"")||a.fontSize!=b.fontSize||a.alignment!=b.alignment||Mathf.Abs(a.color.r-b.color.r)+Mathf.Abs(a.color.g-b.color.g)+Mathf.Abs(a.color.b-b.color.b)+Mathf.Abs(a.color.a-b.color.a)>1e-5)throw new Exception("UI visual/state mismatch after reload: "+go.name+" expected="+JsonUtility.ToJson(a)+" actual="+JsonUtility.ToJson(b)+" blockers="+string.Join(";",p.blockers));
  if(!a.canvas&&((a.anchorMin-b.anchorMin).sqrMagnitude>1e-8||(a.anchorMax-b.anchorMax).sqrMagnitude>1e-8||(a.pivot-b.pivot).sqrMagnitude>1e-8||(a.position-b.position).sqrMagnitude>1e-6||(a.size-b.size).sqrMagnitude>1e-6))throw new Exception("UI RectTransform layout mismatch after reload");
  if(a.texture!=b.texture||a.sprite!=b.sprite||a.spriteName!=b.spriteName||(a.uv-b.uv).sqrMagnitude>1e-8||(a.spriteRect-b.spriteRect).sqrMagnitude>1e-6||(a.spritePivot-b.spritePivot).sqrMagnitude>1e-8||Mathf.Abs(a.pixelsPerUnit-b.pixelsPerUnit)>1e-5||a.textureWidth!=b.textureWidth||a.textureHeight!=b.textureHeight)throw new Exception("UI texture/sprite/UV/reference mismatch after reload: "+go.name);
  if(a.onClick.Count!=b.onClick.Count)throw new Exception("UI callback count mismatch");for(int i=0;i<a.onClick.Count;i++)if(JsonUtility.ToJson(a.onClick[i])!=JsonUtility.ToJson(b.onClick[i]))throw new Exception("UI callback target/method/order mismatch after reload");
 }
